import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));String word = reader.readLine();if (word == null) return;word = word.trim();int zCount = 0;int oCount = 0;for (int i = 0; i < word.length(); i++) {char c = word.charAt(i);if (c == 'z') {zCount++;} else if (c == 'o') {oCount++;}}if (2 * zCount == oCount) {System.out.println("Yes");} else {System.out.println("No");}}}